import { Component, createEffect, createSignal, For, onMount, Show } from "solid-js";
import { createStore } from "solid-js/store";

import * as Validation from "#core/ui/utilities/utilities-validation.js";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { createEngineEvent } from "#core/ui-next/utilities/game-core-utilities.js";

const yieldBarEntryClassMap: Record<string, string> = {
	YIELD_GOLD: "text-yield-gold",
	YIELD_CULTURE: "text-yield-culture",
	YIELD_SCIENCE: "text-yield-science",
	YIELD_DIPLOMACY: "text-yield-influence",
	YIELD_HAPPINESS: "text-yield-happiness",
	YIELD_CITIES: "text-secondary",
	YIELD_CITY_CAP: "fxs-header",
};

interface YieldBarEntryProps {
	type: string;
	yield: number;
	stored?: number;
	max?: number;
	tooltip: string;
	omitPrefix?: boolean;
	useLegacyTooltips?: boolean;
}
const YieldStatusBarEntryComponent: Component<YieldBarEntryProps> = (props) => {
	const [isMobileViewExperience, setIsMobileViewExperience] = createSignal<boolean>(false);
	const [valueText, setValueText] = createSignal<string>("");
	const [iconUrl, setIconUrl] = createSignal<string>("");

	createEffect(() => {
		setIsMobileViewExperience(UI.getViewExperience() === UIViewExperience.Mobile);
	});

	createEffect(() => {
		// <current>/<max> | 4/6
		if (props.max !== undefined) {
			setValueText(`${props.yield}/${props.max}`);
			return;
		}

		const prefix = props.omitPrefix ? "" : props.yield >= 0 ? "+" : "";

		// <stored> (+<value-per-turn) | 88 (+5)
		if (props.stored !== undefined) {
			setValueText(`${props.stored} (${prefix}${props.yield})`);
			return;
		}

		// +<value-per-turn> | +5
		setValueText(`${prefix}${props.yield}`);
	});

	createEffect(() => {
		setIconUrl(`url("blp:${UI.getIconBLP(props.type)}")`);
	});

	const content = (
		<div
			class={`flex items-center text-base font-title ${yieldBarEntryClassMap[props.type]} pointer-events-auto`}
			data-audio-group-ref="audio-yield-panel"
		>
			<Icon
				class="mr-0\.5"
				classList={{
					"size-8 font-title": !isMobileViewExperience(),
					"size-10 font-body-lg": isMobileViewExperience(),
				}}
				name={iconUrl()}
				isUrl
			/>
			<span class="whitespace-nowrap">{valueText()}</span>
		</div>
	);
	return (
		<Show
			when={props.useLegacyTooltips}
			fallback={
				<Tooltip.Text
					text={props.tooltip}
					showFiligrees={false}
				>
					{content}
				</Tooltip.Text>
			}
		>
			<Tooltip.LegacyText text={props.tooltip}>{content}</Tooltip.LegacyText>
		</Show>
	);
};

const YieldStatusBarComponent: Component = () => {
	const [yieldBarEntries, setYieldBarEntries] = createStore<Record<YieldType, YieldBarEntryProps>>({
		YIELD_GOLD: {
			type: "YIELD_GOLD",
			yield: 0,
			tooltip: "LOC_YIELD_GOLD_TREASURY",
		},
		YIELD_SCIENCE: {
			type: "YIELD_SCIENCE",
			yield: 0,
			tooltip: "LOC_YIELD_SCIENCE",
		},
		YIELD_CULTURE: {
			type: "YIELD_CULTURE",
			yield: 0,
			tooltip: "LOC_YIELD_CULTURE",
		},
		YIELD_HAPPINESS: {
			type: "YIELD_HAPPINESS",
			yield: 0,
			tooltip: "LOC_YIELD_HAPPINESS",
		},
		YIELD_DIPLOMACY: {
			type: "YIELD_DIPLOMACY",
			yield: 0,
			tooltip: "LOC_YIELD_DIPLOMACY",
		},
		YIELD_CITIES: {
			type: "YIELD_CITIES",
			yield: 0,
			tooltip: "LOC_YIELD_MAX_CITIES",
		},
		YIELD_CITY_CAP: {
			type: "YIELD_CITY_CAP",
			yield: 0,
			tooltip: "LOC_YIELD_CITY_CAP",
		},
	});

	const ResourceAssignedEvent = createEngineEvent("ResourceAssigned");
	const ResourceUnassignedEvent = createEngineEvent("ResourceUnassigned");

	const player = Players.get(GameContext.localObserverID);

	const updateYield = (type: YieldType) => {
		if (!player?.Stats || !player?.Treasury || !player?.DiplomacyTreasury) {
			console.error("yield-bar.tsx::updateYield: Required player libraries were missing");
			return;
		}

		const yieldEntry = yieldBarEntries[type];

		if (!yieldEntry) {
			return;
		}

		// yieldEntry is a proxy because of the store, but we need a pure YieldBarEntryProps object to update the store in a moment
		const yieldObject: YieldBarEntryProps = {
			type: yieldEntry.type,
			yield: yieldEntry.yield,
			tooltip: yieldEntry.tooltip,
		};

		switch (type) {
			case "YIELD_GOLD": {
				yieldObject.yield = Validation.number({
					value: player.Stats.getNetYield(YieldTypes.YIELD_GOLD).toString(),
					defaultValue: 0,
				});
				yieldObject.stored = Validation.number({
					value: player.Treasury.goldBalance.toString(),
					defaultValue: 0,
				});
				break;
			}
			case "YIELD_SCIENCE": {
				yieldObject.yield = Validation.number({
					value: player.Stats.getNetYield(YieldTypes.YIELD_SCIENCE).toString(),
					defaultValue: 0,
				});
				break;
			}
			case "YIELD_CULTURE": {
				yieldObject.yield = Validation.number({
					value: player.Stats.getNetYield(YieldTypes.YIELD_CULTURE).toString(),
					defaultValue: 0,
				});
				break;
			}
			case "YIELD_HAPPINESS": {
				yieldObject.yield = Validation.number({
					value: player.Stats.getNetYield(YieldTypes.YIELD_HAPPINESS).toString(),
					defaultValue: 0,
				});
				break;
			}
			case "YIELD_DIPLOMACY": {
				yieldObject.yield = Validation.number({
					value: player.Stats.getNetYield(YieldTypes.YIELD_DIPLOMACY).toString(),
					defaultValue: 0,
				});
				yieldObject.stored = Validation.number({
					value: player.DiplomacyTreasury.diplomacyBalance.toString(),
					defaultValue: 0,
				});
				break;
			}
			case "YIELD_CITIES": {
				yieldObject.yield = Validation.number({
					value: player.Stats.numSettlements.toString(),
					defaultValue: 0,
				});
				yieldObject.max = Validation.number({
					value: player.Stats.settlementCap.toString(),
					defaultValue: 0,
				});
				break;
			}
			case "YIELD_CITY_CAP": {
				yieldObject.yield = Validation.number({
					value: player?.Stats?.numCities.toString(),
					defaultValue: 0,
				});
				yieldObject.max = Validation.number({
					value: player.Cities?.getCityLimit().toString(),
					defaultValue: 0,
				});
				break;
			}
		}

		setYieldBarEntries(type, yieldObject);
	};

	const updateAllYields = () => {
		Object.keys(yieldBarEntries).forEach((key) => {
			updateYield(key);
		});
	};

	createEffect(() => {
		const resourceAssignedEventData = ResourceAssignedEvent();
		if (!resourceAssignedEventData) {
			return;
		}
		if (resourceAssignedEventData.player != GameContext.localPlayerID) {
			//Not us, we don't need to update
			return;
		}
		updateAllYields();
	});

	createEffect(() => {
		const resourceUnassignedEventData = ResourceUnassignedEvent();
		if (!resourceUnassignedEventData) {
			return;
		}
		if (resourceUnassignedEventData.player != GameContext.localPlayerID) {
			//Not us, we don't need to update
			return;
		}
		updateAllYields();
	});

	onMount(() => {
		updateAllYields();
	});

	return (
		<div class="absolute h-8 fullscreen-top-outside-safezone">
			<div class="relative flex flex-row">
				<For each={Object.entries(yieldBarEntries)}>
					{([key, value]) => {
						if (key == "YIELD_CITY_CAP" && player?.Cities?.getCityLimit() == 0) {
							return null;
						}

						return <Show when={value}>{(entry) => <YieldStatusBarEntryComponent {...entry()} />}</Show>;
					}}
				</For>
			</div>
		</div>
	);
};

export const YieldStatusBar = ComponentRegistry.register({
	name: "YieldStatusBar",
	createInstance: YieldStatusBarComponent,
});

export const YieldStatusBarEntry = ComponentRegistry.register({
	name: "YieldStatusBarEntry",
	createInstance: YieldStatusBarEntryComponent,
});
